package org.overengineer.bettacraft.client.model;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.model.HierarchicalModel;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.util.FastColor;
import net.minecraft.util.Mth;
import org.overengineer.bettacraft.entity.betta.BettaEntity;

/**
 * Betta entity model (vanilla LayerDefinition from {@link BettaModelDefinitions}, generated by tools/assetgen).
 * Animation is code: tail beat, fin undulation, pectoral flapping. Females have shorter fins, sick fish clamped fins
 * and a weaker beat.
 */
public class BettaModel extends HierarchicalModel<BettaEntity> {
    private final ModelPart root;
    private final ModelPart body, head, peduncle, caudal, dorsal, anal;
    private final ModelPart pecL, pecR, dumboL, dumboR, ventL, ventR;
    private final ModelPart[] fins;
    /** Colour for the next (base) render pass, consumed once; 0 = none. Set by the renderer. */
    private int pendingBaseColor;

    public BettaModel(ModelPart root) {
        this.root = root;
        this.body = root.getChild("body");
        this.head = body.getChild("head");
        this.peduncle = body.getChild("peduncle");
        this.caudal = peduncle.getChild("caudal");
        this.dorsal = body.getChild("dorsal");
        this.anal = body.getChild("anal");
        this.pecL = body.getChild("pectoral_left");
        this.pecR = body.getChild("pectoral_right");
        this.dumboL = body.getChild("pectoral_dumbo_left");
        this.dumboR = body.getChild("pectoral_dumbo_right");
        this.ventL = body.getChild("ventral_left");
        this.ventR = body.getChild("ventral_right");
        this.fins = new ModelPart[]{dorsal, anal, pecL, pecR, dumboL, dumboR, ventL, ventR};
    }

    @Override
    public ModelPart root() {
        return root;
    }

    public void setPendingBaseColor(int argb) {
        this.pendingBaseColor = argb;
    }

    @Override
    public void renderToBuffer(PoseStack poseStack, VertexConsumer buffer, int packedLight, int packedOverlay, int color) {
        if (pendingBaseColor != 0) {
            color = color == -1 ? pendingBaseColor : FastColor.ARGB32.multiply(color, pendingBaseColor);
            pendingBaseColor = 0;
        }
        super.renderToBuffer(poseStack, buffer, packedLight, packedOverlay, color);
    }

    @Override
    public void setupAnim(BettaEntity fish, float limbSwing, float limbSwingAmount, float age, float netHeadYaw, float headPitch) {
        root.getAllParts().forEach(ModelPart::resetPose);
        boolean dumbo = fish.genome().isDumbo();
        pecL.visible = pecR.visible = !dumbo;
        dumboL.visible = dumboR.visible = dumbo;

        boolean sick = fish.isSick();
        boolean water = fish.isInWater();
        float speed = water ? (sick ? 0.6F : 1.0F) : 1.8F;
        float amp = water ? (sick ? 0.4F : 1.0F) : 1.6F;
        float t = age * speed;

        float beat = Mth.sin(t * 0.35F);
        peduncle.yRot = Mth.sin(t * 0.35F - 0.6F) * 0.18F * amp;
        caudal.yRot = beat * 0.42F * amp;
        dorsal.yRot = Mth.sin(t * 0.3F + 1.0F) * 0.07F * amp;
        anal.yRot = Mth.sin(t * 0.3F + 2.0F) * 0.07F * amp;
        dorsal.xRot = Mth.sin(t * 0.2F) * 0.04F * amp;
        float flap = Mth.sin(t * 0.9F) * 0.28F * amp;
        pecL.yRot += flap;
        pecR.yRot -= flap;
        dumboL.yRot += flap * 0.8F;
        dumboR.yRot -= flap * 0.8F;
        ventL.xRot += Mth.sin(t * 0.4F) * 0.08F * amp;
        ventR.xRot += Mth.sin(t * 0.4F + 0.5F) * 0.08F * amp;

        float finScale = fish.isFemale() ? BettaModelDefinitions.FEMALE_FIN_SCALE : 1.0F;
        float tailScale = fish.isFemale() ? BettaModelDefinitions.FEMALE_TAIL_SCALE : 1.0F;
        // young fish: fins still short (fry 0.5, juvenile 0.7, subadult 0.85)
        float young = switch (fish.lifeStage()) {
            case FRY, EGG, LARVA -> 0.5F;
            case JUVENILE -> 0.7F;
            case SUBADULT -> 0.85F;
            default -> 1.0F;
        };
        finScale *= young;
        tailScale *= young;
        for (ModelPart p : fins) scale(p, finScale, finScale, finScale);
        scale(caudal, tailScale, tailScale, tailScale);
        if (fish.genome().isShortFinned()) {
            // plakat types: same mesh, shorter unpaired fins
            float s = BettaModelDefinitions.SHORT_FIN_SCALE;
            scale(caudal, 1.0F, BettaModelDefinitions.SHORT_CAUDAL_HEIGHT, BettaModelDefinitions.SHORT_CAUDAL_LENGTH);
            scale(dorsal, s, s, s);
            scale(anal, s, s, s);
        }
        float fl = sick ? 0 : fish.flareAmount(age - fish.tickCount);
        if (fl > 0) {
            // flaring: fins spread wide, gill covers open (head slightly wider), a slow gentle shimmy; eased in and
            // out (the flag toggles often in fights) and slow - the old 5 Hz pulse looked like the fish trembled
            float shiver = 1.0F + Mth.sin(age * 0.45F) * 0.02F * fl;
            scale(caudal, 1.0F, (1.0F + 0.22F * fl) * shiver, 1.0F + 0.12F * fl);
            scale(dorsal, 1.0F, (1.0F + 0.3F * fl) * shiver, 1.0F + 0.1F * fl);
            scale(anal, 1.0F, (1.0F + 0.3F * fl) * shiver, 1.0F + 0.1F * fl);
            scale(head, 1.0F + 0.18F * fl, 1.0F + 0.06F * fl, 1.0F);
            pecL.yRot += 0.35F * fl;
            pecR.yRot -= 0.35F * fl;
        }
        if (sick) {
            // clamped fins: folded closer to the body
            scale(caudal, 1.0F, 0.75F, 0.7F);
            scale(dorsal, 1.0F, 0.7F, 0.8F);
            scale(anal, 1.0F, 0.7F, 0.8F);
            caudal.yRot *= 0.5F;
        }
    }

    private static void scale(ModelPart p, float x, float y, float z) {
        p.xScale *= x;
        p.yScale *= y;
        p.zScale *= z;
    }
}
